# Quick validation: ensure HTML is well-formed and contains all required sections
from html.parser import HTMLParser

class SimpleValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.sections = set()
        self.img_count = 0
        self.has_html = False
        self.has_body = False
    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        if tag == 'section':
            for attr, val in attrs:
                if attr == 'id':
                    self.sections.add(val)
        if tag == 'img':
            self.img_count += 1
        if tag == 'html':
            self.has_html = True
        if tag == 'body':
            self.has_body = True
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()

with open('/app/output/final_report.html', 'r', encoding='utf-8') as f:
    content = f.read()

